// Biểu tượng thương hiệu Shoppost nhúng base64 để Worker tự phục vụ (không cần static assets binding).
// Nguồn: shoppost_icon_final_1024.png (nền gradient navy #030213 → tím chàm, chữ "S" trắng Inter Display Bold).
const ASSETS = {
  '/favicon.ico': { type: 'image/x-icon', data: '' },
  '/apple-touch-icon.png': { type: 'image/png', data: '' },
  '/og-image.png': { type: 'image/png', data: '' }
};
const decoded = new Map();
export function brandAssetResponse(path, method) {
  const asset = ASSETS[path];
  if (!asset) return null;
  if (method !== 'GET' && method !== 'HEAD') return new Response('Chỉ hỗ trợ GET hoặc HEAD.', { status: 405, headers: { Allow: 'GET, HEAD', 'Content-Type': 'text/plain; charset=utf-8' } });
  if (!decoded.has(path)) decoded.set(path, Uint8Array.from(atob(asset.data), c => c.charCodeAt(0)));
  const bytes = decoded.get(path);
  return new Response(method === 'HEAD' ? null : bytes, { headers: {
    'Content-Type': asset.type, 'Content-Length': String(bytes.length),
    'Cache-Control': 'public, max-age=86400', 'X-Content-Type-Options': 'nosniff'
  } });
}
